contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(bytes memory data) public payable {
        require(data.length > 0);
        uint before = address(c).balance;
        c.forward(address(c), data); if (__ESBMC_reverted()) return;
        assert(address(c).balance == before);
    }
    receive() external payable {}
    fallback() external payable {}
}

